const mode = msg.payload.lockingMode;
const deviceId = msg.payload.deviceId;

if (mode === -1) {
    // Curfew just engaged one-way (exit blocked). Only escalate to a full
    // lock once every chip has been seen inside - otherwise a straggler
    // gets locked out entirely. Unknown status (no pet poll yet) counts
    // as "someone might still be out", so we stay on the app's own lock.
    if (flow.get('anyPetOutside') !== false) {
        return null;
    }
    msg.payload = { deviceId, lockState: 3 };
    return msg;
}

if (mode === -2) {
    // Curfew released - drop back to unlocked regardless of pet locations
    msg.payload = { deviceId, lockState: 0 };
    return msg;
}

// Any other mode (manual override, curfew disabled, unknown) - leave it alone
return null;

// Keep a running per-pet inside/outside map in flow context, keyed by
// chip/pet id, and derive a single anyPetOutside flag from it. Starts
// unknown (undefined) until every pet has been seen at least once.
const pets = flow.get('petLocations') || {};
pets[msg.payload.id] = msg.payload.where; // 1 = inside, 2 = outside
flow.set('petLocations', pets);
flow.set('anyPetOutside', Object.values(pets).some(where => where === 2));
return null;
